cmd:
cat > /work/old-t7/system/controlDict << 'EOF'
FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object controlDict;
}
application     buoyantSimpleFoam;
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         1;
deltaT          1;
writeControl    timeStep;
writeInterval   1;
purgeWrite      0;
writeFormat     ascii;
writePrecision  6;
writeCompression off;
timeFormat      general;
timePrecision   6;
runTimeModifiable true;
EOF

cat > /work/old-t7/system/fvSchemes << 'EOF'
FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object fvSchemes;
}
ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
EOF

cat > /work/old-t7/system/fvSolution << 'EOF'
FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object fvSolution;
}
solvers {}
EOF

cd /work/old-t7 && ./Allmesh
